import math
import sys

if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)
sys.setrecursionlimit(100000)


def evaluate(expr: str) -> int:
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if "0" <= c <= "9":
            j = i
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(("NUM", int(expr[i:j])))
            i = j
        elif c in "+-*/%^!()":
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    processed = []
    for tok in tokens:
        if processed:
            prev = processed[-1]
            if tok[0] == "NUM" and prev[0] in ("NUM", ")", "!"):
                raise ValueError("Malformed expression")
            if tok[0] == "(" and prev[0] in ("NUM", ")", "!"):
                processed.append(("*", "*"))
        processed.append(tok)
    tokens = processed

    pos = 0

    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise ValueError("Division by zero")
        sign = -1 if (a < 0) ^ (b < 0) else 1
        return sign * (abs(a) // abs(b))

    def trunc_mod(a: int, b: int) -> int:
        if b == 0:
            raise ValueError("Remainder by zero")
        return a - trunc_div(a, b) * b

    def parse_expr() -> int:
        return parse_add()

    def parse_add() -> int:
        nonlocal pos
        val = parse_mul()
        while pos < len(tokens) and tokens[pos][0] in ("+", "-"):
            op = tokens[pos][0]
            pos += 1
            right = parse_mul()
            if op == "+":
                val = val + right
            else:
                val = val - right
        return val

    def parse_mul() -> int:
        nonlocal pos
        val = parse_unary()
        while pos < len(tokens) and tokens[pos][0] in ("*", "/", "%"):
            op = tokens[pos][0]
            pos += 1
            right = parse_unary()
            if op == "*":
                val = val * right
            elif op == "/":
                val = trunc_div(val, right)
            elif op == "%":
                val = trunc_mod(val, right)
        return val

    def parse_unary() -> int:
        nonlocal pos
        if pos < len(tokens) and tokens[pos][0] == "-":
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_power() -> int:
        nonlocal pos
        base = parse_postfix()
        if pos < len(tokens) and tokens[pos][0] == "^":
            pos += 1
            exp = parse_unary()
            if exp < 0:
                raise ValueError("Negative exponent")
            return pow(base, exp)
        return base

    def parse_postfix() -> int:
        nonlocal pos
        val = parse_atom()
        while pos < len(tokens) and tokens[pos][0] == "!":
            pos += 1
            if val < 0:
                raise ValueError("Factorial of a negative number")
            val = math.factorial(val)
        return val

    def parse_atom() -> int:
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        tok = tokens[pos]
        if tok[0] == "NUM":
            pos += 1
            return tok[1]
        elif tok[0] == "(":
            pos += 1
            val = parse_expr()
            if pos >= len(tokens) or tokens[pos][0] != ")":
                raise ValueError("Expected ')'")
            pos += 1
            return val
        else:
            raise ValueError(f"Unexpected token: {tok[0]}")

    result = parse_expr()
    if pos < len(tokens):
        raise ValueError("Unexpected token at end of expression")
    return result
